local function isMainLobby()
    if game.PlaceId == 77649408247578 or game.PlaceId == 2414851778 then return true end
    local dName = Workspace:FindFirstChild("dungeonName")
    if dName and dName:IsA("StringValue") and #dName.Value > 0 then return false end
    local dObj = Workspace:FindFirstChild("dungeon")
    if dObj then return false end
    return true
end

local function isDungeon()
    return not isMainLobby()
end

local function getMatchProgress()
    local dProg = Workspace:FindFirstChild("dungeonProgress")
    if dProg and dProg:IsA("StringValue") and #dProg.Value > 0 then
        local v = dProg.Value:lower()
        if v:find("victory") or v:find("complete") or v:find("bosskilled") or v:find("defeat") or v:find("failed") or v:find("loss") then
            return v
        end
    end
    local timeLeft = Workspace:FindFirstChild("timeLeft")
    if timeLeft and timeLeft:IsA("NumberValue") and timeLeft.Value <= 0.5 then
        return "defeat"
    end
    local pG = LocalPlayer:FindFirstChild("PlayerGui")
    if pG then
        local fail = pG:FindFirstChild("DUNGEON FAILED", true) or pG:FindFirstChild("Defeat", true) or pG:FindFirstChild("RetryVote", true)
        if fail and ((fail:IsA("GuiObject") and fail.Visible) or (fail:IsA("ScreenGui") and fail.Enabled)) then
            return "defeat"
        end
    end
    return nil
end

-- ========================================================================
--  PASSIVE AUTO-SELL (100% SAFE: CRYSTALLINE & OVERGROWN PROTECTED)
-- ========================================================================
local function runSafeAutoSell()
    if not Config.AutoSellTrashes or not sellItemEventRemote then return end
    local pG = LocalPlayer:FindFirstChild("PlayerGui")
    if not pG then return end
    local invGui = pG:FindFirstChild("inventoryGui") or pG:FindFirstChild("invyGui")
    if not invGui then return end
    
    local itemsFolder = invGui:FindFirstChild("items", true) or invGui:FindFirstChild("grid", true)
    if not itemsFolder then return end

    local PROTECTED_NAMES = { "crystalline", "overgrown", "tree", "ancient", "titan" }

    for _, frame in ipairs(itemsFolder:GetChildren()) do
        if frame:IsA("GuiObject") and frame.Visible then
            local itemName = frame.Name
            local titleObj = frame:FindFirstChild("title") or frame:FindFirstChild("itemName") or frame:FindFirstChild("TextLabel")
            if titleObj and titleObj:IsA("TextLabel") and #titleObj.Text > 0 then
                itemName = titleObj.Text
            end

            local isProtected = false
            for _, prot in ipairs(PROTECTED_NAMES) do
                if itemName:lower():find(prot) then
                    isProtected = true
                    break
                end
            end

            if not isProtected then
                local rarityColor = frame:FindFirstChild("rarity") or frame
                local isSellableRarity = false
                if rarityColor and rarityColor:IsA("GuiObject") then
                    local c = rarityColor.BackgroundColor3
                    -- Purple / Rare / Common / Uncommon
                    if (c.R > 0.4 and c.B > 0.4 and c.G < 0.3) or (c.R < 0.3 and c.G > 0.5 and c.B > 0.5) or (c.R > 0.8 and c.G > 0.8 and c.B > 0.8) then
                        isSellableRarity = true
                    end
                end
                
                if isSellableRarity then
                    pcall(function()
                        sellItemEventRemote:FireServer(frame.Name)
                    end)
                end
            end
        end
    end
end

