local function sendDiscordNotification(title, description, color)
    if not Config.DiscordWebhook or #Config.DiscordWebhook < 10 then return end
    local payload = {
        embeds = {{
            title = title,
            description = description,
            color = color or 5814783,
            footer = { text = "Project Maki • EF-Copy Master 1 Suite" },
            timestamp = DateTime.now():ToIsoDate()
        }}
    }
    local ok, encoded = pcall(function() return HttpService:JSONEncode(payload) end)
    if ok and encoded then
        local httpRequest = (syn and syn.request) or (http and http.request) or http_request or (Fluxus and Fluxus.request) or request
        if httpRequest then
            pcall(function()
                httpRequest({
                    Url = Config.DiscordWebhook,
                    Method = "POST",
                    Headers = { ["Content-Type"] = "application/json" },
                    Body = encoded
                })
            end)
        end
    end
end

-- ========================================================================
--  HIGHWAY PATHFINDING & MOB DETECTION ENGINE
-- ========================================================================
local function getActiveEnemies()
    local enemies = {}
    local dObj = Workspace:FindFirstChild("dungeon")
    local eFolder = (dObj and dObj:FindFirstChild("enemies")) or Workspace:FindFirstChild("enemies")
    
    if eFolder then
        for _, enemy in ipairs(eFolder:GetChildren()) do
            local hum = enemy:FindFirstChildOfClass("Humanoid")
            local root = enemy:FindFirstChild("HumanoidRootPart") or enemy:FindFirstChild("Torso") or enemy:FindFirstChild("Head")
            if hum and root and hum.Health > 0 then
                table.insert(enemies, {
                    model = enemy,
                    humanoid = hum,
                    root = root,
                    pos = root.Position,
                    name = enemy.Name,
                    isBoss = (enemy.Name:lower():find("tree") or enemy.Name:lower():find("ancient") or enemy.Name:lower():find("dragon") or enemy.Name:lower():find("boss") or hum.MaxHealth > 50000)
                })
            end
        end
    end
    return enemies
end

local function getNearestEnemyGroup(myPos, range)
    local enemies = getActiveEnemies()
    local nearby = {}
    local nearestDist = 999999
    local nearestEnemy = nil
    local bossFound = nil

    for _, e in ipairs(enemies) do
        local d = (e.pos - myPos).Magnitude
        if d < nearestDist then
            nearestDist = d
            nearestEnemy = e
        end
        if d <= (range or Config.CombatRange) then
            table.insert(nearby, e)
        end
        if e.isBoss and d <= 250 then
            bossFound = e
        end
    end

    return {
        nearest = nearestEnemy,
        nearestDist = nearestDist,
        group = nearby,
        count = #nearby,
        boss = bossFound,
        allEnemies = enemies
    }
end

