    local function triggerQ()
        if not canUseQ() then return false end
        qCooldownEndTime = tick() + 6.0
        qBuffEndTime = tick() + 4.5
        pcall(function()
            if abilityUsedRemote then abilityUsedRemote:FireServer("Q") end
            if abilityCastRemote then abilityCastRemote:FireServer("Q") end
            VirtualInputManager:SendKeyEvent(true, Enum.KeyCode.Q, false, game)
            task.wait(0.02)
            VirtualInputManager:SendKeyEvent(false, Enum.KeyCode.Q, false, game)
        end)
        return true
    end

    local function triggerE()
        if not canUseE() then return false end
        eCooldownEndTime = tick() + 8.0
        pcall(function()
            if abilityUsedRemote then abilityUsedRemote:FireServer("E") end
            if abilityCastRemote then abilityCastRemote:FireServer("E") end
            VirtualInputManager:SendKeyEvent(true, Enum.KeyCode.E, false, game)
            task.wait(0.02)
            VirtualInputManager:SendKeyEvent(false, Enum.KeyCode.E, false, game)
        end)
        return true
    end

    -- Pre-Boss Watchdog variables
    local preBossWatchdogStart = 0
    local lastPreBossWp = 0
    local preBossReplayTriggered = false

    local lastAutoSellTime = 0

    while _G.MAKI_EF_COPY_MASTER_1_RUNNING do
        task.wait(0.02)

        if isMainLobby() or not isDungeon() then
            treeKilled = false
            minWpFloor = 1
            currentWpIndex = 1
            preBossWatchdogStart = 0
            lastPreBossWp = 0
            preBossReplayTriggered = false
            task.wait(0.5)
            continue
        end

        local char = LocalPlayer.Character
        local hrp = char and (char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Torso"))
        local hum = char and char:FindFirstChildOfClass("Humanoid")

        if hrp and hum and hum.Health > 0 then
            local myPos = hrp.Position
            local now = tick()

            -- Periodic Auto-Sell
            if (now - lastAutoSellTime) >= 3.0 then
                lastAutoSellTime = now
                runSafeAutoSell()
            end

            -- Match End / Victory / Defeat Instant Detection
            local matchStatus = getMatchProgress()
            if matchStatus then
                statusLbl.Text = string.format("● STATUS: 🏆 MATCH OVER (%s) -> AUTO RETRYING", matchStatus:upper())
                statusLbl.TextColor3 = Color3.fromRGB(0, 255, 200)
                infoLbl.Text = "🔄 Match Complete -> Auto Replaying Dungeon..."
                
                pcall(function() readyUpRemote:FireServer() end)
                task.wait(0.3)

                local data = { dungeonName = "Enchanted Forest", dungeonProgress = "bossKilled", hardcore = Config.HardcoreMode or false }
                if replayRemote then
                    pcall(function() replayRemote:FireServer(data) end)
                    pcall(function() replayRemote:FireServer("bossKilled") end)
                    pcall(function() replayRemote:FireServer() end)
                end
                pcall(function() readyUpRemote:FireServer() end)
                task.wait(1.5)
                continue
            end

            -- ================================================================
            --  [PRE-BOSS FAST-REPLAY WATCHDOG] (WP 850 - 930)
            -- ================================================================
            if currentWpIndex >= 850 and currentWpIndex <= 930 and not preBossReplayTriggered then
                if lastPreBossWp == currentWpIndex then
                    if preBossWatchdogStart == 0 then
                        preBossWatchdogStart = now
                    elseif (now - preBossWatchdogStart) >= 2.5 then
                        preBossReplayTriggered = true
                        print(string.format("[Maki Watchdog ⚡] Stalled at Pre-Boss WP %d for %.1fs! Triggering Auto-Retry Dungeon scapegoat...", currentWpIndex, now - preBossWatchdogStart))
                        statusLbl.Text = "● STATUS: ⚡ PRE-BOSS STALL -> AUTO-RETRYING DUNGEON..."
                        statusLbl.TextColor3 = Color3.fromRGB(255, 80, 80)
                        infoLbl.Text = string.format("🔄 Auto Retry Scapegoat Fired at WP %d", currentWpIndex)

                        local data = { dungeonName = "Enchanted Forest", dungeonProgress = "bossKilled", hardcore = Config.HardcoreMode or false }
                        if replayRemote then
                            pcall(function() replayRemote:FireServer(data) end)
                            pcall(function() replayRemote:FireServer("bossKilled") end)
                            pcall(function() replayRemote:FireServer() end)
                        end
                        pcall(function() readyUpRemote:FireServer() end)
                        task.wait(1.5)
                        continue
                    end
                else
                    lastPreBossWp = currentWpIndex
                    preBossWatchdogStart = now
                end
            else
                preBossWatchdogStart = 0
            end

            -- Staging Wait Guard
            local pG = LocalPlayer:FindFirstChild("PlayerGui")
            local qG = pG and pG:FindFirstChild("queueGui")
            if qG and qG.Enabled then
                task.wait(0.2)
                continue
            end

            -- ================================================================
            --  ROOM 5 ANCIENT TREE BOSS LOCK (WP 701 -> 745)
            -- ================================================================
            local distToTree = (Vector3.new(TREE_CENTER_POS.X, myPos.Y, TREE_CENTER_POS.Z) - myPos).Magnitude
            if distToTree <= 160 and not treeKilled and currentWpIndex >= 680 and currentWpIndex <= 745 then
                local bossGroup = getNearestEnemyGroup(myPos, 200)
                local bossModel = bossGroup.boss and bossGroup.boss.model
                local bossHum = bossGroup.boss and bossGroup.boss.humanoid
                local bossRoot = bossGroup.boss and bossGroup.boss.root

                if bossModel and bossHum and bossRoot and bossHum.Health > 0 then
                    local targetPlatform = TREE_PLATFORM_EDGE
                    local distToEdge = (Vector3.new(targetPlatform.X, myPos.Y, targetPlatform.Z) - myPos).Magnitude
                    
                    if distToEdge > 5.0 then
                        hum:MoveTo(targetPlatform)
                    else
                        hum:MoveTo(myPos)
                    end

                    local dToBoss = (bossRoot.Position - myPos).Magnitude
                    local hpPercent = math.floor((bossHum.Health / bossHum.MaxHealth) * 100)
                    targetLbl.Text = string.format("🎯 BOSS: %s (HP: %d%% | %d studs)", bossModel.Name, hpPercent, math.floor(dToBoss))

                    -- Staggered Q -> E Boss Combat
                    if dToBoss <= Config.QBuffRange and canUseQ() and not isQBuffActive() then
                        triggerQ()
                    end

                    if dToBoss <= Config.CombatRange then
                        if canUseE() then
                            if canUseQ() and not isQBuffActive() then triggerQ() end
                            triggerE()
                        end
                        if weaponUsedRemote then
                            pcall(function() weaponUsedRemote:FireServer(bossModel) end)
                        end
                    end
                    continue
                else
                    treeKilled = true
                    if minWpFloor < 745 then minWpFloor = 745 end
                    currentWpIndex = math.max(currentWpIndex, 745)
                    print("[Maki Tree 🌳] Room 5 Ancient Tree Defeated! Jumping Highway to WP 745...")
                end
            end

            -- ================================================================
            --  DRAGON BOSS ARENA (WP 950 - 1015)
            -- ================================================================
            if currentWpIndex >= 950 then
                local dragonGroup = getNearestEnemyGroup(myPos, 220)
                if dragonGroup.boss then
                    local dRoot = dragonGroup.boss.root
                    local dHum = dragonGroup.boss.humanoid
                    local dModel = dragonGroup.boss.model
                    local dDist = (dRoot.Position - myPos).Magnitude
                    local hpPercent = math.floor((dHum.Health / dHum.MaxHealth) * 100)

                    targetLbl.Text = string.format("🐉 DRAGON: %s (HP: %d%% | %d studs)", dModel.Name, hpPercent, math.floor(dDist))

                    if dDist <= Config.QBuffRange and canUseQ() and not isQBuffActive() then
                        triggerQ()
                    end

                    if dDist <= Config.CombatRange then
                        if canUseE() then
                            if canUseQ() and not isQBuffActive() then triggerQ() end
                            triggerE()
                        end
                        if weaponUsedRemote then
                            pcall(function() weaponUsedRemote:FireServer(dModel) end)
                        end
                    end
                end
            end

            -- ================================================================
            --  STANDARD HIGHWAY NAVIGATION & STAGGERED COMBAT
            -- ================================================================
            local targetGroup = getNearestEnemyGroup(myPos, Config.QBuffRange)
            local nearestEnemy = targetGroup.nearest

            if targetGroup.count > 0 and nearestEnemy then
                targetLbl.Text = string.format("🎯 MOB: %s (Count: %d | %d studs)", nearestEnemy.name, targetGroup.count, math.floor(targetGroup.nearestDist))
            else
                targetLbl.Text = "🎯 TARGET: Searching Highway for Enemies..."
            end

            -- Combat Execution
            if nearestEnemy then
                -- 1. Pre-buff Q at 115 studs
                if targetGroup.nearestDist <= Config.QBuffRange and targetGroup.nearestDist > Config.StandoffRange then
                    if canUseQ() and not isQBuffActive() then
                        triggerQ()
                    end
                end

                -- 2. Standoff Line at 85 studs when cooldowns not ready
                if targetGroup.nearestDist <= Config.StandoffRange then
                    if not canUseE() and not isQBuffActive() and targetGroup.nearestDist < Config.StandoffRange then
                        -- Hold position outside mob 71-stud aggro radius
                        hum:MoveTo(myPos)
                    end
                end

                -- 3. Q+E Wipe at 82 studs
                if targetGroup.nearestDist <= Config.CombatRange then
                    if canUseE() then
                        if canUseQ() and not isQBuffActive() then triggerQ() end
                        triggerE()
                    end
                    if weaponUsedRemote then
                        for _, e in ipairs(targetGroup.group) do
                            pcall(function() weaponUsedRemote:FireServer(e.model) end)
                        end
                    end
                end
            end

            -- Centerline Highway Progression
            if EMBEDDED_WAYPOINTS and #EMBEDDED_WAYPOINTS > 0 then
                -- Find nearest valid forward waypoint
                local searchStart = math.max(1, minWpFloor)
                local searchEnd = math.min(#EMBEDDED_WAYPOINTS, searchStart + 80)
                local bestIdx = currentWpIndex
                local bestDist = 999999

                for i = searchStart, searchEnd do
                    local wp = EMBEDDED_WAYPOINTS[i]
                    if wp then
                        local wpPos = Vector3.new(wp[1], wp[2], wp[3])
                        local d = (wpPos - myPos).Magnitude
                        if d < bestDist then
                            bestDist = d
                            bestIdx = i
                        end
                    end
                end

                if bestIdx > minWpFloor then minWpFloor = bestIdx end
                currentWpIndex = bestIdx

                -- Update HUD
                local pct = math.floor((currentWpIndex / totalWaypoints) * 100)
                wpLbl.Text = string.format("📍 HIGHWAY: %d / %d (%d%%)", currentWpIndex, totalWaypoints, pct)

                -- Compute Lookahead Target Waypoint
                local targetWpIdx = math.min(#EMBEDDED_WAYPOINTS, currentWpIndex + math.floor(Config.LookaheadDist / 4))
                local targetWp = EMBEDDED_WAYPOINTS[targetWpIdx]
                if targetWp then
                    local targetPos = Vector3.new(targetWp[1], targetWp[2], targetWp[3])
                    hum:MoveTo(targetPos)
                end
            end
        end
    end
end)

print(string.format("[Project Maki 🌲] EF-Copy Master 1 loaded for %s (👑 Master / Main Mode)!", LocalPlayer.Name))
